    (v_aula_id, 1, $p$A carta aponta que a prosperidade faz o homem sentir que "encontrou seu lugar no mundo", quando na verdade é o mundo que se aloja nele; em que medida seu conforto, sua reputação e seu trabalho absorvente têm criado em você a sensação de estar "em casa" na terra e enfraquecido o apetite pelo Céu?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Fitafuso aposta no desgaste lento da meia-idade, na "exaustão" e no silencioso desespero de quem deixa de perseverar; onde você sente esse cansaço de continuar firme, e que práticas concretas o ajudam no difícil "ato da perseverança" diante das tentações crônicas?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$O demônio diz que o melhor modo de prender o jovem é fazê-lo crer que a terra pode virar paraíso pela política, pela ciência ou pela psicologia; quanto da sua esperança você tem depositado em projetos humanos de progresso, e como recolocar essa esperança naquilo que só Deus realiza?$p$, 'reflexao', null);
  end if;

